steps.command:
python3 - <<'EOF'
s=open('schema/vulnerability/os/schema-1.1.0.json').read()
old='''                "Module": {
                  "type": ["string", "null"]
                }
'''
assert old in s
s=s.replace(old,'''                "Module": {
                  "type": ["string", "null"]
                },
                "Arch": {
                  "type": "string"
                }
''')
open('schema/vulnerability/os/schema-1.1.1.json','w').write(s)
EOF
grep -n "1.1.0" schema/vulnerability/os/schema-1.1.1.json; sed -n 425,470p tests/unit/providers/oracle/test_oracle.py; .venv/bin/python -m pytest -q 2>&1 | tail -15
